// The schema table as a JSON Schema (draft 2020-12), for editors (the YAML language server) and for Python or R code that
// validates before writing a file. Generated by `npm run docs:config`; never edited by hand. It checks shape and types; what
// only code can know (a colour the browser accepts, a vocab entry's fields, a page file that exists) is left to `check`.
import { SETTINGS, SCHEMA_VERSION, type SettingDef } from './schema'

type Json = Record<string, unknown>

function leaf(row: SettingDef): Json {
  const base: Json = { description: row.description }
  switch (row.type) {
    case 'string':
    case 'color':
      return { type: 'string', ...base }
    case 'url':
      return { type: 'string', pattern: '^\\S*$', ...base }
    case 'number':
      return { type: 'number', ...base }
    case 'integer':
      return { type: 'integer', ...base }
    case 'boolean':
      return { type: 'boolean', ...base }
    case 'boolean|string':
      return { type: ['boolean', 'string'], ...base }
    case 'enum':
      return { enum: [...(row.values ?? [])], ...base }
    case 'map':
      return { type: 'object', ...base }
    case 'list': {
      const items = row.of === 'integer' ? { type: 'integer' } : row.of ? { type: 'string' } : {}
      return { type: 'array', items, ...base }
    }
  }
}

export function renderJsonSchema(schema: readonly SettingDef[] = SETTINGS): Json {
  const root: Json = {
    $schema: 'https://json-schema.org/draft/2020-12/schema',
    title: 'dashboard-config.yaml',
    description: `Site settings of the calibration dashboard (file version ${SCHEMA_VERSION}). Generated from src/config/schema.ts.`,
    type: 'object',
    additionalProperties: false,
    properties: {},
  }
  for (const row of schema) {
    let node = root
    const parts = row.path.split('.')
    for (const key of parts.slice(0, -1)) {
      const props = node.properties as Json
      if (!props[key]) props[key] = { type: 'object', additionalProperties: false, properties: {} }
      node = props[key] as Json
    }
    ;(node.properties as Json)[parts[parts.length - 1]] = leaf(row)
  }
  return root
}

export function renderJsonSchemaText(schema: readonly SettingDef[] = SETTINGS): string {
  return `${JSON.stringify(renderJsonSchema(schema), null, 2)}\n`
}
